13	// 预览的当前标识与来源标识都是最新记录，并返回其完整状态。
14	func TestPreviewRecoveryHealthySelectsCurrent(t *testing.T) {
15		a, _ := newTestArchive(t)
16		ids := saveN(t, a, "s", 2) // r2 r1 r0
17	
18		pv, err := a.PreviewRecovery("s", []string{"v1"})
19		if err != nil {
20			t.Fatalf("预览失败: %v", err)
21		}
22		if pv.Current != ids[0] || pv.Source != ids[0] {
23			t.Fatalf("完好槽应选当前记录: current=%s source=%s latest=%s",
24				pv.Current, pv.Source, ids[0])
25		}
26		if pv.State.Time != 2 || pv.State.Seed != 42 || pv.State.Rules.Version != "v1" {
27			t.Fatalf("预览状态与最新记录不符: %+v", pv.State)
28		}
29	}
30	
