32	// 损坏记录本身，来源按保存次序越过受损记录落到最近完好记录，并返回其完整
33	// 世界状态。
34	func TestPreviewRecoveryAcrossDamagedRecords(t *testing.T) {
35		a, dir := newTestArchive(t)
36		ids := saveN(t, a, "s", 4) // r4 r3 r2 r1 r0
37		truncateRecord(t, dir, ids[0])
38		corruptChecksum(t, dir, ids[1])
39	
40		pv, err := a.PreviewRecovery("s", []string{"v1"})
41		if err != nil {
42			t.Fatalf("应越过受损记录预览: %v", err)
43		}
44		if pv.Current != ids[0] {
45			t.Fatalf("当前标识应为受损的 %s，得到 %s", ids[0], pv.Current)
46		}
47		if pv.Source != ids[2] {
48			t.Fatalf("来源应为 %s，得到 %s", ids[2], pv.Source)
49		}
50		// ids[2] 对应时间片 2，内容完整。
51		if pv.State.Time != 2 || pv.State.Seed != 42 {
52			t.Fatalf("来源状态错误: %+v", pv.State)
53		}
54		chars := pv.State.Characters
55		if len(chars) != 2 || chars[0].ID != "hero" ||
56			!reflect.DeepEqual(chars[0].Items, []CharacterItem{{Item: "gold", Count: 1}}) {
57			t.Fatalf("角色/物品未完整返回: %+v", chars)
