// 自洽且时间片非负，否则返回 *RuleError。入参会被深拷贝。
func WorldFromState(st State) (*World, error) {
	if st.Time < 0 {
		return nil, ruleErrorf("时间片不能为负: %d", st.Time)
	}
	if err := validateInitialData(InitialData{
